/** Compact Host workflow generated by `stetra init`. */

import { hostAdapterDefinition, type HostAdapter } from './definition.ts';

export type { HostAdapter } from './definition.ts';

export function renderHostSkill(adapter: HostAdapter): string {
  const host = hostAdapterDefinition(adapter).displayName;
  return `---
name: stetra
description: Preserve developer understanding and adoption authority for an admitted coding change.
---

# Stetra

Stetra is embedded in ${host}; it is not a separate coding Agent. Use the
developer's normal conversation and ${host}'s normal investigation,
implementation, test, and repair loop.

## Admit and align

Follow the admission policy injected by the SessionStart Hook. Do nothing for
conversation-only work or a declined task. For an admitted coding task, call
\`stetra task begin\` before editing with one compact JSON input containing:

- the exact current developer request as \`humanEvent.content\`;
- your concise \`desiredOutcome\`, \`constraints\`, and \`nonGoals\`;
- \`assurance: { "mode": "routine" }\` unless the developer or project policy
  explicitly declares a consequential concern;
- exact argv checks, a configured verification profile, or a concrete
  no-command rationale.

Use the opaque \`--binding-token\` projected by the Hook when present. Do not
read or edit Stetra canonical task files. Relay the Human text byte-for-byte;
the current thin adapter records it as unattested input and does not claim
native prompt identity.

## Work

Implement normally. When the implementation is ready, call \`stetra task
collect\` once. If a frozen Check is not passing, use its exact result and
bounded log as ordinary engineering feedback, repair normally, and collect
again. Only an actual timeout may be retried by calling task collect with
--retry-timeout <check-key> and --timeout-ms <larger-ms>, within the returned
bound. No Stetra diagnosis document is required.

## Decide

After current facts exist, call \`stetra task handoff\` with a compact current
explanation: actual behavior, at least one mechanism, only material optional
invariants/failure paths/effects/tradeoffs, bounded unknowns and review focus,
and one recommendation. Reference facts by readable changed path or Check key.

Present the returned \`decisionBrief\`, state that adoption is pending, ask the
developer to accept, request correction, reject, or defer, and stop. Only a new
developer message may be passed to \`stetra task decide\`. Acceptance with
Attention requires the developer to explicitly acknowledge it.

Runtime facts, Agent judgment, and Human authority remain distinct. Passing
checks are observations, not adoption. Never invent Runtime facts, hide adverse
evidence, infer assurance from repository shape, or claim this thin adapter
attests a capability it does not control.
`;
}

export function renderHostPointerBlock(
  adapter: HostAdapter,
  markers: { start: string; end: string },
): string {
  const skillPath = `${hostAdapterDefinition(adapter).skillRoot}/SKILL.md`;
  return `${markers.start}
For an admitted Agent-authored coding change, follow [the generated Stetra skill](${skillPath}).
${markers.end}`;
}
